import * as THREE from 'three';
// Hipped roof: four slopes, each >= 5 overlapping strips that droop progressively and overhang the eave; a sagging ridge.
export function makeHippedRoof(w, d, pitchDeg = 32, rng = Math.random, strips = 6) {
  const roof = new THREE.Group(); roof.userData.tag = 'roof';
  const rise = Math.tan(THREE.MathUtils.degToRad(pitchDeg)) * Math.min(w, d) * 0.5, overhang = 0.2;   // overhang >= 0.15
  for (const [yaw, span, depth] of [[0, w, d], [Math.PI / 2, d, w], [Math.PI, w, d], [-Math.PI / 2, d, w]]) {
    const slope = new THREE.Group(); slope.rotation.y = yaw; roof.add(slope);
    const run = depth * 0.5 + overhang, theta = Math.atan2(rise, run);
    for (let i = 0; i < strips; i++) {                                    // i = 0 at the ridge, last strip at the eave
      const tHi = 1 - i / strips, tLo = Math.max(0, 1 - (i + 1) / strips - 0.1);   // 10% overlap with the strip below
      const yHi = rise * tHi, yLo = rise * tLo, zHi = run * (1 - tHi), zLo = run * (1 - tLo);
      const droop = THREE.MathUtils.degToRad(6 * i);                        // each lower strip 5-10 deg steeper than the one above
      const geo = new THREE.PlaneGeometry(span * (1 - 0.45 * tHi) + 2 * overhang, Math.hypot(zLo - zHi, yHi - yLo));
      const l = 0.28 + (rng() - 0.5) * 0.08;                                // per-strip value jitter, +-8% lightness
      const m = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(0.08, 0.35, l), roughness: 0.95, flatShading: true, side: THREE.DoubleSide }));
      m.position.set(0, (yHi + yLo) / 2, (zHi + zLo) / 2);
      m.rotation.x = theta + droop - Math.PI / 2;
      m.userData.tag = 'roof-strip'; slope.add(m);
    }
  }
  const half = (Math.max(w, d) - Math.min(w, d)) * 0.5 + 0.3, sag = 0.07 * Math.max(w, d);   // ridge dips 5-10% of span mid-way
  const curve = new THREE.CatmullRomCurve3([new THREE.Vector3(-half, rise, 0), new THREE.Vector3(0, rise - sag, 0), new THREE.Vector3(half, rise, 0)]);
  const ridge = new THREE.Mesh(new THREE.TubeGeometry(curve, 12, 0.12, 6, false), new THREE.MeshStandardMaterial({ color: 0x3a2e24, roughness: 0.9 }));
  if (w < d) ridge.rotation.y = Math.PI / 2;
  ridge.userData.tag = 'ridge'; roof.add(ridge);
  return roof;
}
